"""Refund pilot fixture + fake dispatcher (UO-3). In-memory only."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

from sector8.pilot import (
    EvaluateAttempt,
    honor_enforce_decision,
    honor_observe_decision,
    should_dispatch,
)

# Staging Refund Agent fixture — confirm with Operator for your tenant.
REFUND_FIXTURE = {
    "environment": "staging",
    "tool_name": "refund.create",
    "currency": "GBP",
    "cap_amount": 100,
    "under_cap_amount": 25,
    "over_cap_amount": 250,
    "expected_deny_reason": "AMOUNT_LIMIT_EXCEEDED",
    "agent_name": "Refund Agent",
    "caller_id": "refund-pilot-walkthrough",
}


@dataclass
class FakeRefundRecord:
    amount: float
    currency: str
    order_id: str


@dataclass
class FakeRefundDispatcher:
    dispatches: List[FakeRefundRecord] = field(default_factory=list)

    def dispatch(self, record: FakeRefundRecord) -> FakeRefundRecord:
        self.dispatches.append(record)
        return record

    @property
    def count(self) -> int:
        return len(self.dispatches)

    def reset(self) -> None:
        self.dispatches.clear()


def refund_evaluate_arguments(amount: float) -> Dict[str, Any]:
    return {
        "amount": amount,
        "currency": REFUND_FIXTURE["currency"],
        "order_id": "ORD-PILOT-001",
        "metadata": {"agent_name": REFUND_FIXTURE["agent_name"]},
    }


def run_enforce_once(
    attempt: EvaluateAttempt,
    dispatcher: FakeRefundDispatcher,
    record: FakeRefundRecord,
) -> Dict[str, Any]:
    before = dispatcher.count
    honor_enforce_decision(attempt, lambda: dispatcher.dispatch(record))
    after = dispatcher.count
    return _report("enforce", attempt, after - before)


def run_observe_once(
    attempt: EvaluateAttempt,
    dispatcher: FakeRefundDispatcher,
    record: FakeRefundRecord,
) -> Dict[str, Any]:
    before = dispatcher.count

    def _workflow() -> bool:
        dispatcher.dispatch(record)
        return True

    result = honor_observe_decision(attempt, _workflow)
    report = _report("observe", attempt, dispatcher.count - before)
    report["continued"] = result.get("continued", True)
    return report


def assert_enforce_effects(attempt: EvaluateAttempt, dispatched_delta: int) -> None:
    if should_dispatch(attempt):
        if dispatched_delta != 1:
            raise AssertionError(
                f"enforce ALLOW expected 1 dispatch, got {dispatched_delta}"
            )
    elif dispatched_delta != 0:
        raise AssertionError(
            f"enforce non-ALLOW expected 0 dispatches, got {dispatched_delta}"
        )


def _report(
    mode: str, attempt: EvaluateAttempt, dispatched: int
) -> Dict[str, Any]:
    if attempt.get("ok"):
        artifact = attempt.get("artifact")
        return {
            "mode": mode,
            "decision": getattr(artifact, "outcome", None),
            "reason_code": getattr(artifact, "reason_code", None),
            "decision_trace_id": getattr(artifact, "decision_trace_id", None),
            "evidence_hash": getattr(artifact, "evidence_hash", None),
            "policy_version_id": getattr(artifact, "policy_version_id", None),
            "dispatched": dispatched,
        }
    return {
        "mode": mode,
        "decision": f"FAIL:{attempt.get('kind')}",
        "failure_kind": attempt.get("kind"),
        "dispatched": dispatched,
    }
